92	function authorizeCronRequest(req: express.Request, res: express.Response): boolean {
93	  const cronSecret = process.env.CRON_SECRET;
94	  if (!cronSecret) {
95	    res.status(503).json({ message: "Cron not configured" });
96	    return false;
97	  }
98	  const provided = req.headers["x-cron-secret"];
99	  const providedBuf = Buffer.from(Array.isArray(provided) ? "" : (provided ?? ""));
100	  const secretBuf = Buffer.from(cronSecret);
101	  if (
102	    providedBuf.length !== secretBuf.length
103	    || !crypto.timingSafeEqual(providedBuf, secretBuf)
104	  ) {
105	    res.status(401).json({ message: "Unauthorized" });
106	    return false;
107	  }
108	  return true;
109	}
