125	async function executeStoredCardCharge(request: StoredCardChargeRequest) {
126	  const outcome = await chargeStoredCard(
127	    request.idempotencyKey,
128	    request.cardId,
129	    (request.amountCents / 100).toFixed(2),
130	    request.reference,
131	  );
132	  if (!outcome.success) {
133	    // Windcave already records a redacted audit event. Keep provider/transport
134	    // detail out of storage result messages that could later reach an API.
135	    return { success: false as const, error: "Stored-card charge could not be confirmed" };
136	  }
137	  return {
138	    success: true as const,
139	    approved: outcome.approved === true,
140	    windcaveTransactionId: outcome.windcaveTransactionId,
141	    declineReason: outcome.declineReason,
142	  };
143	}
