33	      scriptSrc: ["'self'", "'unsafe-inline'", "https://pay.google.com", "https://applepay.cdn-apple.com", "https://uat.windcave.com", "https://sec.windcave.com"],
34	      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
35	      fontSrc: ["'self'", "https://fonts.gstatic.com"],
36	      imgSrc: ["'self'", "data:", "blob:", "https:"],
37	      connectSrc: ["'self'", "https://uat.windcave.com", "https://sec.windcave.com", "https://pay.google.com"],
38	      frameSrc: ["'self'", "https://sec.windcave.com", "https://uat.windcave.com", "https://pay.google.com"],
39	      objectSrc: ["'none'"],
40	      baseUri: ["'self'"],
41	      formAction: ["'self'"],
42	      upgradeInsecureRequests: [],
43	    },
44	  } : false,
