64	  "script-src 'self'",
65	  "style-src 'self' 'unsafe-inline'",
66	  "connect-src 'self'",
67	  "img-src 'self' data:",
68	  "font-src 'self'",
69	  "object-src 'none'",
70	  "base-uri 'none'",
