89	// Gzip compression for all responses — skips already-compressed assets and
90	// very small payloads (< 1 KB) where compression overhead outweighs savings.
91	app.use(compression({ threshold: 1024 }));
92	
93	// Development can exercise the isolated in-memory sandbox. Production is an
94	// autoscale deployment without proven sticky routing, so mounting the Map-backed
95	// service there would strand sessions across instances. Keep it fail-closed
96	// until the deployment-store gate in the landing plan is resolved.
