137	(async () => {
138	  // ── JWT_SECRET validation ────────────────────────────────────────────────
139	  if (!process.env.JWT_SECRET) {
140	    if (isProduction) {
141	      console.error('');
142	      console.error('[FATAL] JWT_SECRET is NOT set in production.');
143	      console.error('  Set JWT_SECRET in your deployment secrets to a strong random value.');
144	      console.error('  Refusing to start — running without JWT_SECRET in production is insecure.');
145	      console.error('');
146	      process.exit(1);
147	    } else {
148	      console.warn('⚠️  JWT_SECRET not set — using development fallback (acceptable in dev only).');
149	      process.env.JWT_SECRET = 'dev-secret-key-change-in-production';
150	    }
151	  } else {
152	    console.log('✅ JWT_SECRET: configured');
153	  }
154	
155	  // ── Database connectivity verification ───────────────────────────────────
156	  // isDatabaseConnected() only checks that the Neon client was initialised.
157	  // Do a real query here to confirm the database is actually reachable before
158	  // accepting any traffic. Fail fast in production; warn only in development.
159	  if (isDatabaseConnected()) {
160	    try {
161	      const db = getDb();
162	      await db!.execute(sql`SELECT 1`);
163	      console.log('✅ Database: connection verified (live query succeeded)');
164	    } catch (error) {
165	      if (isProduction) {
166	        console.error('FATAL: Database is unreachable after connection was established:');
167	        console.error(error);
168	        console.error('Refusing to start — merchant data cannot be read or written.');
169	        process.exit(1);
170	      } else {
171	        console.warn('⚠️  Database live-query check failed (continuing in dev mode):', error);
172	      }
173	    }
174	  }
175	
176	  // ── Read-only migration gate ─────────────────────────────────────────────
177	  // Production must never accept traffic against pending, drifted, orphaned,
178	  // or out-of-order schema history. Development reports the same issues loudly.
179	  try {
180	    const { reportPendingMigrations } = await import("./migrate");
181	    await reportPendingMigrations({ failOnIssues: isProduction });
182	  } catch (error) {
183	    if (isProduction) {
184	      console.error("[FATAL] Database migration gate failed.");
185	      console.error(error);
186	      process.exit(1);
187	    }
188	    log(`⚠️  Migration check unavailable (non-fatal in development): ${error}`);
189	  }
190	
191	  // ── Schema push (drizzle-kit push) ───────────────────────────────────────
192	  // Never run schema sync as a normal app-start side effect. The trades branch
193	  // must use reviewed additive SQL, and drizzle-kit push can propose destructive
194	  // live-DB changes. Opt in only for a deliberate, supervised run.
195	  //
196	  // DATA SAFETY: --force is intentionally omitted. Without --force, drizzle-kit
197	  // refuses to apply destructive changes (column drops, table drops) and returns
198	  // a non-zero exit code instead of silently destroying live data. If you need
199	  // to apply schema changes, run `npm run db:push` manually after reviewing
200	  // exactly what will be changed, or start with RUN_SCHEMA_PUSH=true.
201	  if (process.env.RUN_MIGRATIONS === 'true') {
202	    console.error('[FATAL] RUN_MIGRATIONS is retired; run `npm run db:migrate` as a deliberate deploy step.');
203	    process.exit(1);
204	  }
205	  const runSchemaPush = process.env.RUN_SCHEMA_PUSH === 'true';
206	  if (isDatabaseConnected() && runSchemaPush) {
207	    log('Running schema push to sync database...');
208	    try {
209	      const drizzleConfigPath = path.resolve(process.cwd(), 'drizzle.config.ts');
210	      const configExists = fs.existsSync(drizzleConfigPath);
211	      if (configExists) {
212	        const push = spawnSync(
213	          'npx',
214	          ['drizzle-kit', 'push', `--config=${drizzleConfigPath}`],
215	          {
216	            stdio: 'pipe',
217	            encoding: 'utf8',
218	            timeout: 30_000,
219	            env: { ...process.env },
220	          }
221	        );
222	        if (push.status === 0) {
223	          log('✅ Schema: database schema is up to date');
224	        } else {
225	          const output = (push.stdout || '') + (push.stderr || '');
226	          // Non-zero exit most likely means a destructive change was blocked.
227	          // The server continues safely — no data was modified.
228	          log(`⚠️  Schema has destructive changes — run \`npm run db:push\` manually to review before applying. Data untouched. Details: ${output.slice(0, 200)}`);
229	        }
230	      } else {
231	        log('⚠️  drizzle.config.ts not found at project root — skipping schema push');
232	      }
233	    } catch (err) {
234	      log(`⚠️  Schema push threw an error (non-fatal): ${err}`);
235	    }
236	  }
237	
238	
239	  const server = await registerRoutes(app);
240	
241	  // Initialize database with seed data if connected
242	  if (isDatabaseConnected()) {
243	    try {
244	      await seedDatabase();
245	    } catch (error) {
246	      log(`⚠️ Database seeding failed: ${error}`);
247	    }
248	  }
249	
250	  // Sync verified merchants to recreate auth users
251	  try {
252	    const { syncVerifiedMerchants } = await import("./auth");
