348	type ProbeOutcome<T> =
349	  /** The server answered and the session is good. */
350	  | { kind: "ok"; value: T }
351	  /** The server looked at the credentials/principal and refused them. */
352	  | { kind: "rejected" }
353	  /** We learned nothing about the credentials. Never a reason to discard them. */
354	  | { kind: "unavailable"; detail: string; retryable: boolean };
