367	/**
368	 * Runs `probe` until it produces a definite answer, or until the bounds above
369	 * are spent — whichever comes first. `onResult` is called exactly once, with a
370	 * result that is never "still waiting".
371	 *
372	 * Returns a cancel function: after it runs, `onResult` can no longer fire, so
373	 * an unmounted consumer is never updated.
374	 */
375	function startBoundedSessionCheck<T>(
376	  probe: (signal: AbortSignal) => Promise<ProbeOutcome<T>>,
377	  onResult: (result: SessionResult<T>) => void,
378	): () => void {
379	  let settled = false;
380	  const timers = new Set<ReturnType<typeof setTimeout>>();
381	  const inFlight = new Set<AbortController>();
382	
383	  const stopEverything = () => {
384	    timers.forEach(clearTimeout);
385	    timers.clear();
386	    inFlight.forEach((controller) => controller.abort());
387	    inFlight.clear();
388	  };
389	
390	  // The single exit. First definite answer wins and cancels everything else, so
391	  // no straggler can revive the check or contradict the state it produced.
392	  const settle = (result: SessionResult<T>) => {
393	    if (settled) return;
394	    settled = true;
395	    stopEverything();
396	    onResult(result);
397	  };
398	
399	  const after = (ms: number, run: () => void) => {
400	    const id = setTimeout(() => {
401	      timers.delete(id);
402	      if (!settled) run();
403	    }, ms);
404	    timers.add(id);
405	    return id;
406	  };
407	
408	  // The backstop. Nothing below is trusted to finish on its own: if the attempt
409	  // sequence is somehow still running when this fires, the check ends here in a
410	  // visible error rather than an open-ended spinner.
411	  after(AUTH_TOTAL_DEADLINE_MS, () => settle({ kind: "unavailable", detail: unreachableDetail() }));
412	
413	  const attempt = async (n: number): Promise<void> => {
414	    const controller = new AbortController();
415	    inFlight.add(controller);
416	    // Covers the whole attempt, response body included — a half-sent body is
417	    // just as good at hanging as a request that is never answered.
418	    const abortAt = after(AUTH_ATTEMPT_TIMEOUT_MS, () => controller.abort());
419	
420	    let outcome: ProbeOutcome<T>;
421	    try {
422	      outcome = await probe(controller.signal);
423	    } catch {
424	      // Network error, DNS failure, offline, or our own abort firing. None of
425	      // these says anything about the credentials.
426	      outcome = { kind: "unavailable", detail: unreachableDetail(), retryable: true };
427	    } finally {
428	      clearTimeout(abortAt);
429	      timers.delete(abortAt);
430	      inFlight.delete(controller);
431	    }
432	
433	    if (settled) return;
434	    if (outcome.kind !== "unavailable") {
435	      settle(outcome);
436	      return;
437	    }
438	    if (outcome.retryable && n < AUTH_MAX_ATTEMPTS) {
439	      const delay = AUTH_RETRY_DELAYS_MS[n - 1] ?? AUTH_RETRY_DELAYS_MS[AUTH_RETRY_DELAYS_MS.length - 1];
440	      after(delay, () => runAttempt(n + 1));
441	      return;
442	    }
443	    settle({ kind: "unavailable", detail: outcome.detail });
444	  };
445	
446	  // Even an unforeseen throw ends in a definite state rather than a dangling
447	  // promise. `settle` is idempotent, so this can never overwrite a real answer.
448	  const runAttempt = (n: number) => {
449	    void attempt(n).catch(() => settle({ kind: "unavailable", detail: unreachableDetail() }));
450	  };
451	
452	  runAttempt(1);
453	  return () => {
454	    settled = true;
455	    stopEverything();
456	  };
457	}
