987	  const tutorialEnabled = auth?.isAuthenticated === true && auth.role !== "admin" && !!auth.merchantId && auth.onboardingCompleted === true;
988	  return (
989	    <TutorialProvider enabled={tutorialEnabled}>
990	      {/* The backstop, above the router rather than inside it, because the
991	          router itself renders things the route-level boundary cannot cover:
992	          the landing page and the desktop chrome branch both live outside that
993	          Suspense. Nothing below this point may take the whole window down to
